import{_ as i,c as a,o as l,ae as t}from"./chunks/framework.DMK_uHmU.js";const p=JSON.parse('{"title":"AI File Manager User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Content/document-uploads.md","filePath":"Administration/AI-Management/Content/document-uploads.md"}'),o={name:"Administration/AI-Management/Content/document-uploads.md"};function n(r,e,s,d,h,u){return l(),a("div",null,e[0]||(e[0]=[t('<h1 id="ai-file-manager-user-guide" tabindex="-1">AI File Manager User Guide <a class="header-anchor" href="#ai-file-manager-user-guide" aria-label="Permalink to &quot;AI File Manager User Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#introduction">Introduction</a></li><li><a href="#getting-started">Getting Started</a></li><li><a href="#uploading-files">Uploading Files</a></li><li><a href="#file-management">File Management</a></li><li><a href="#knowledge-base-association">Knowledge Base Association</a></li><li><a href="#file-information">File Information</a></li><li><a href="#publish-attributes">Publish Attributes</a></li><li><a href="#advanced-features">Advanced Features</a></li><li><a href="#viewing-files">Viewing Files</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The AI File Manager is a powerful tool that allows you to upload, manage, and associate documents with AI knowledge bases. This guide will walk you through the process of uploading files, configuring their attributes, and preparing them for AI processing.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><h3 id="accessing-the-file-manager" tabindex="-1">Accessing the File Manager <a class="header-anchor" href="#accessing-the-file-manager" aria-label="Permalink to &quot;Accessing the File Manager&quot;">​</a></h3><ol><li>Navigate to the AI File Manager in the content management section</li><li>You&#39;ll see the main interface with upload area and configuration panels</li><li>If editing an existing file, the interface will display the current file&#39;s information</li></ol><h3 id="understanding-the-interface" tabindex="-1">Understanding the Interface <a class="header-anchor" href="#understanding-the-interface" aria-label="Permalink to &quot;Understanding the Interface&quot;">​</a></h3><p>The AI File Manager has three main sections:</p><ul><li><strong>File Upload Area</strong> (left/center): Where you upload and manage files</li><li><strong>File Information Panel</strong> (right top): Configure basic file details</li><li><strong>Publish Attributes Panel</strong> (right middle): Set categorization and scheduling options</li></ul><h2 id="uploading-files" tabindex="-1">Uploading Files <a class="header-anchor" href="#uploading-files" aria-label="Permalink to &quot;Uploading Files&quot;">​</a></h2><h3 id="single-file-upload" tabindex="-1">Single File Upload <a class="header-anchor" href="#single-file-upload" aria-label="Permalink to &quot;Single File Upload&quot;">​</a></h3><ol><li>If no Knowledge Base is selected, first select at least one Knowledge Base using the dropdown at the top</li><li>Click the &quot;+&quot; button or drag and drop a file into the upload area</li><li>The file will appear in the upload queue with its name and size</li><li>The system automatically populates the Display Name based on the file name</li></ol><h3 id="multiple-file-upload" tabindex="-1">Multiple File Upload <a class="header-anchor" href="#multiple-file-upload" aria-label="Permalink to &quot;Multiple File Upload&quot;">​</a></h3><ol><li>Select at least one Knowledge Base using the dropdown at the top</li><li>Drag and drop multiple files or click the &quot;+&quot; button to select multiple files</li><li>Each file will appear in the upload queue</li><li>Note: When uploading multiple files, the common Display Name and Description fields are disabled</li></ol><h3 id="file-name-and-description-editing" tabindex="-1">File Name and Description Editing <a class="header-anchor" href="#file-name-and-description-editing" aria-label="Permalink to &quot;File Name and Description Editing&quot;">​</a></h3><p>For files in the upload queue:</p><ol><li>Click the pencil icon next to the file name</li><li>In the dialog that appears, enter the new file name and description</li><li>Click &quot;Save&quot; to apply these changes</li></ol><h3 id="starting-the-upload" tabindex="-1">Starting the Upload <a class="header-anchor" href="#starting-the-upload" aria-label="Permalink to &quot;Starting the Upload&quot;">​</a></h3><ol><li>After configuring all necessary attributes, click the &quot;Upload&quot; button</li><li>The upload progress will be indicated with a status label</li><li>Successful uploads will be marked with a green &quot;Succeeded&quot; badge</li><li>Failed uploads will show an error message</li></ol><h2 id="file-management" tabindex="-1">File Management <a class="header-anchor" href="#file-management" aria-label="Permalink to &quot;File Management&quot;">​</a></h2><h3 id="viewing-existing-files" tabindex="-1">Viewing Existing Files <a class="header-anchor" href="#viewing-existing-files" aria-label="Permalink to &quot;Viewing Existing Files&quot;">​</a></h3><p>When accessing an existing file:</p><ol><li>The file details are displayed in the center of the interface</li><li>You&#39;ll see the file name, size, type, and last update information</li><li>Click &quot;View File&quot; to open the file viewer</li></ol><h3 id="uploading-new-versions" tabindex="-1">Uploading New Versions <a class="header-anchor" href="#uploading-new-versions" aria-label="Permalink to &quot;Uploading New Versions&quot;">​</a></h3><p>To replace an existing file with a new version:</p><ol><li>Click &quot;Upload New Version&quot;</li><li>Select the new file from your device</li><li>The new file will replace the existing one while maintaining all settings</li></ol><h3 id="deleting-files" tabindex="-1">Deleting Files <a class="header-anchor" href="#deleting-files" aria-label="Permalink to &quot;Deleting Files&quot;">​</a></h3><ol><li>Click the &quot;Delete&quot; button in the top right corner</li><li>Confirm the deletion in the popup dialog</li><li>The file and its associated content will be removed from the system</li></ol><h2 id="knowledge-base-association" tabindex="-1">Knowledge Base Association <a class="header-anchor" href="#knowledge-base-association" aria-label="Permalink to &quot;Knowledge Base Association&quot;">​</a></h2><p>Knowledge Base association is required for AI processing:</p><ol><li>Select one or more Knowledge Bases from the dropdown at the top</li><li>Files must be associated with at least one Knowledge Base to be processed by AI</li><li>If you attempt to upload without selecting a Knowledge Base, an error message will appear</li><li>You can change Knowledge Base associations after upload</li></ol><h2 id="file-information" tabindex="-1">File Information <a class="header-anchor" href="#file-information" aria-label="Permalink to &quot;File Information&quot;">​</a></h2><p>Configure basic file details in the File Information panel:</p><ol><li><p><strong>Display Name</strong>: The name that appears in listings and search results</p><ul><li>Automatically populated based on the file name but can be customized</li><li>Required field</li></ul></li><li><p><strong>Description</strong>: Additional information about the file content</p><ul><li>Optional but recommended for better search results</li><li>Appears in file listings</li></ul></li></ol><h2 id="publish-attributes" tabindex="-1">Publish Attributes <a class="header-anchor" href="#publish-attributes" aria-label="Permalink to &quot;Publish Attributes&quot;">​</a></h2><p>The Publish Attributes panel allows detailed configuration:</p><h3 id="tags-and-topics" tabindex="-1">Tags and Topics <a class="header-anchor" href="#tags-and-topics" aria-label="Permalink to &quot;Tags and Topics&quot;">​</a></h3><ol><li><p><strong>Tags</strong>: Add multiple tags to categorize the file</p><ul><li>Type a tag name and press Enter to add it</li><li>Select from existing tags or create new ones</li><li>Tags help with content organization and discovery</li></ul></li><li><p><strong>Topic</strong>: Select a single topic that best describes the file</p><ul><li>Choose from the predefined topic list</li><li>Topics are used for high-level categorization and reporting</li></ul></li></ol><h3 id="publishing-schedule" tabindex="-1">Publishing Schedule <a class="header-anchor" href="#publishing-schedule" aria-label="Permalink to &quot;Publishing Schedule&quot;">​</a></h3><p>Control when content is available:</p><ol><li><p><strong>Start Date</strong>: When the content will become available</p><ul><li>Click to open a date/time picker</li><li>Leave blank for immediate availability</li></ul></li><li><p><strong>End Date</strong>: When the content will no longer be available</p><ul><li>Click to open a date/time picker</li><li>Leave blank for permanent availability</li></ul></li></ol><h3 id="featured-content" tabindex="-1">Featured Content <a class="header-anchor" href="#featured-content" aria-label="Permalink to &quot;Featured Content&quot;">​</a></h3><p>Make content appear in featured sections:</p><ol><li>Toggle &quot;Featured Content Enabled&quot; to on</li><li>Configure featured presentation: <ul><li><strong>Title</strong>: Short, attention-grabbing headline</li><li><strong>Description</strong>: Brief summary of the content</li><li><strong>Featured Image URL</strong>: Web address of an image to display</li></ul></li><li>A preview card shows how the featured content will appear</li></ol><h2 id="advanced-features" tabindex="-1">Advanced Features <a class="header-anchor" href="#advanced-features" aria-label="Permalink to &quot;Advanced Features&quot;">​</a></h2><h3 id="meta-information" tabindex="-1">Meta Information <a class="header-anchor" href="#meta-information" aria-label="Permalink to &quot;Meta Information&quot;">​</a></h3><p>View detailed file metadata by expanding the Meta Information panel:</p><ul><li>File Name: Original name of the uploaded file</li><li>Content Type: Document, image, video, etc.</li><li>File Size: Both upload and compressed sizes</li><li>File Extension: File format</li><li>Content ID: Unique identifier</li><li>AI Process Status: Current AI processing state</li><li>File Added: Creation date and user</li><li>File Updated: Last modification date and user</li></ul><h2 id="viewing-files" tabindex="-1">Viewing Files <a class="header-anchor" href="#viewing-files" aria-label="Permalink to &quot;Viewing Files&quot;">​</a></h2><h3 id="file-preview" tabindex="-1">File Preview <a class="header-anchor" href="#file-preview" aria-label="Permalink to &quot;File Preview&quot;">​</a></h3><ol><li>Click &quot;View File&quot; to open the file viewer</li><li>The viewer interface adapts based on the file type: <ul><li>PDF, Office documents: Interactive document viewer</li><li>Videos: Video player with controls</li><li>Text files: Formatted text viewer</li><li>HTML: Code view with option to view live page</li></ul></li></ol><h3 id="video-transcription" tabindex="-1">Video Transcription <a class="header-anchor" href="#video-transcription" aria-label="Permalink to &quot;Video Transcription&quot;">​</a></h3><p>For video files, a transcription feature is available:</p><ol><li>Open the video in the viewer</li><li>Click on the &quot;Video Transcription&quot; accordion below the player</li><li>Transcription will be displayed when available</li></ol><h3 id="text-file-viewing" tabindex="-1">Text File Viewing <a class="header-anchor" href="#text-file-viewing" aria-label="Permalink to &quot;Text File Viewing&quot;">​</a></h3><p>For text-based files (TXT, CSV, JSON, etc.):</p><ol><li>Content is displayed with appropriate formatting</li><li>For HTML files, you can toggle between code view and &quot;View Live Page&quot;</li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="upload-issues" tabindex="-1">Upload Issues <a class="header-anchor" href="#upload-issues" aria-label="Permalink to &quot;Upload Issues&quot;">​</a></h3><p>If files fail to upload:</p><ol><li>Check the error message for specific issues</li><li>Verify file size is under the 110MB limit</li><li>Ensure Knowledge Base is selected</li><li>Check that you have proper permissions</li></ol><h3 id="ai-processing" tabindex="-1">AI Processing <a class="header-anchor" href="#ai-processing" aria-label="Permalink to &quot;AI Processing&quot;">​</a></h3><p>After successful upload:</p><ol><li>Files need to be processed by AI before appearing in knowledge bases</li><li>Processing time depends on file size and type</li><li>Large documents may take several minutes to process</li><li>You can check processing status in the Meta Information panel</li></ol><h3 id="help-resources" tabindex="-1">Help Resources <a class="header-anchor" href="#help-resources" aria-label="Permalink to &quot;Help Resources&quot;">​</a></h3><p>For additional assistance:</p><ol><li>Click the &quot;Help&quot; button for context-specific guidance</li><li>Review the information about Tags, Knowledge Bases, and Topics</li><li>Contact your administrator for system-specific questions</li></ol>',69)]))}const g=i(o,[["render",n]]);export{p as __pageData,g as default};
